package bridge

// Wire parity of the Groupcast cluster and the AccessControl Auxiliary
// surface against bytes matter.js produced: TlvOfModel(element) for every
// Groupcast command, the Membership and AuxiliaryAcl attributes (encoded as
// a non-fabric-filtered read encodes them, a fabric-sensitive field allowed
// to be missing) and the GroupcastTesting / AuxiliaryAccessUpdated events.
// Generated by notes/parity/matter/generate-group-fixtures.ts groupcast.

import (
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"slices"
	"strconv"
	"testing"

	mattercore "github.com/SukramJ/go-fabric/cluster/core"
	"github.com/SukramJ/go-fabric/im"
	"github.com/SukramJ/go-fabric/tlv"
)

//go:embed testdata/groupcast-wire-fixtures.json
var groupcastWireFixturesJSON []byte

type groupcastWireFixture struct {
	Label    string          `json:"label"`
	Kind     string          `json:"kind"`
	Element  string          `json:"element"`
	Fixture  json.RawMessage `json:"fixture"`
	BytesHex string          `json:"bytesHex"`
}

// gcFixtureFields is the union of the Groupcast payload fields.
type gcFixtureFields struct {
	GroupID          uint16   `json:"groupId"`
	Endpoints        []uint16 `json:"endpoints"`
	KeySetID         uint16   `json:"keySetId"`
	Key              string   `json:"key"`
	UseAuxiliaryACL  *bool    `json:"useAuxiliaryAcl"`
	ReplaceEndpoints *bool    `json:"replaceEndpoints"`
	McastAddrPolicy  *uint8   `json:"mcastAddrPolicy"`
	TestOperation    uint8    `json:"testOperation"`
	DurationSeconds  *uint16  `json:"durationSeconds"`
}

func hexBytes(t *testing.T, s string) []byte {
	t.Helper()
	if s == "" {
		return nil
	}
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

// encodeValue runs v through the production attribute / event value writer.
func encodeValue(t *testing.T, v any) string {
	t.Helper()
	enc := tlv.NewEncoder()
	defaultAttributeValueWriter(enc, tlv.AnonymousTag(), im.AttributeValue{Value: v})
	b, err := enc.Bytes()
	if err != nil {
		t.Fatalf("encode: %v", err)
	}
	return hex.EncodeToString(b)
}

func TestGroupcastPayloadsMatchMatterJS(t *testing.T) {
	t.Parallel()
	var fixtures []groupcastWireFixture
	if err := json.Unmarshal(groupcastWireFixturesJSON, &fixtures); err != nil || len(fixtures) == 0 {
		t.Fatalf("groupcast-wire-fixtures.json: %v (%d entries)", err, len(fixtures))
	}
	for _, f := range fixtures {
		t.Run(f.Label, func(t *testing.T) {
			t.Parallel()
			switch f.Kind {
			case "commands":
				checkGroupcastCommandFixture(t, f)
			case "attributes":
				checkGroupcastAttributeFixture(t, f)
			case "events":
				checkGroupcastEventFixture(t, f)
			default:
				t.Fatalf("unknown fixture kind %q", f.Kind)
			}
		})
	}
}

func checkGroupcastCommandFixture(t *testing.T, f groupcastWireFixture) {
	t.Helper()
	var fx gcFixtureFields
	if err := json.Unmarshal(f.Fixture, &fx); err != nil {
		t.Fatal(err)
	}
	decoded := func(cmd uint32) any { return decodeCommandFields(t, mattercore.GroupcastClusterID, cmd, f.BytesHex) }
	switch f.Element {
	case "JoinGroup":
		got := decoded(0x00).(mattercore.JoinGroupRequest)
		if got.GroupID != fx.GroupID || !slices.Equal(got.Endpoints, fx.Endpoints) || got.KeySetID != fx.KeySetID ||
			!slices.Equal(got.Key, hexBytes(t, fx.Key)) || (got.Key == nil) != (fx.Key == "") ||
			!eqPtr(got.UseAuxiliaryACL, fx.UseAuxiliaryACL) || !eqPtr(got.ReplaceEndpoints, fx.ReplaceEndpoints) || !eqPtr(got.McastAddrPolicy, fx.McastAddrPolicy) {
			t.Fatalf("decoded %+v, want %+v", got, fx)
		}
	case "LeaveGroup":
		got := decoded(0x01).(mattercore.LeaveGroupRequest)
		if got.GroupID != fx.GroupID || got.HasEndpoints != (fx.Endpoints != nil) || !slices.Equal(got.Endpoints, fx.Endpoints) {
			t.Fatalf("decoded %+v, want %+v", got, fx)
		}
	case "UpdateGroupKey":
		got := decoded(0x03).(mattercore.UpdateGroupKeyRequest)
		if got.GroupID != fx.GroupID || got.KeySetID != fx.KeySetID || !slices.Equal(got.Key, hexBytes(t, fx.Key)) {
			t.Fatalf("decoded %+v, want %+v", got, fx)
		}
	case "ConfigureAuxiliaryAcl":
		got := decoded(0x04).(mattercore.ConfigureAuxiliaryACLRequest)
		if got.GroupID != fx.GroupID || got.UseAuxiliaryACL != *fx.UseAuxiliaryACL {
			t.Fatalf("decoded %+v, want %+v", got, fx)
		}
	case "GroupcastTesting":
		got := decoded(0x05).(mattercore.GroupcastTestingRequest)
		if got.TestOperation != fx.TestOperation || !eqPtr(got.DurationSeconds, fx.DurationSeconds) {
			t.Fatalf("decoded %+v, want %+v", got, fx)
		}
	case "LeaveGroupResponse":
		if got := encodeCommandFields(t, mattercore.LeaveGroupResponse{GroupID: fx.GroupID, Endpoints: fx.Endpoints}); got != f.BytesHex {
			t.Fatalf("encoded %s\n  matter.js %s", got, f.BytesHex)
		}
	default:
		t.Fatalf("unknown command %s", f.Element)
	}
}

func eqPtr[T comparable](a, b *T) bool {
	if a == nil || b == nil {
		return a == nil && b == nil
	}
	return *a == *b
}

func checkGroupcastAttributeFixture(t *testing.T, f groupcastWireFixture) {
	t.Helper()
	switch f.Element {
	case "Membership":
		var fx []struct {
			GroupID         uint16   `json:"groupId"`
			Endpoints       []uint16 `json:"endpoints"`
			KeySetID        *uint16  `json:"keySetId"`
			HasAuxiliaryACL bool     `json:"hasAuxiliaryAcl"`
			McastAddrPolicy uint8    `json:"mcastAddrPolicy"`
			FabricIndex     uint8    `json:"fabricIndex"`
		}
		if err := json.Unmarshal(f.Fixture, &fx); err != nil {
			t.Fatal(err)
		}
		var v []mattercore.GroupcastMembershipStruct
		for _, m := range fx {
			v = append(v, mattercore.GroupcastMembershipStruct{
				GroupID: m.GroupID, Endpoints: m.Endpoints, KeySetID: m.KeySetID,
				HasAuxiliaryACL: m.HasAuxiliaryACL, McastAddrPolicy: m.McastAddrPolicy, FabricIndex: m.FabricIndex,
			})
		}
		if got := encodeValue(t, v); got != f.BytesHex {
			t.Fatalf("encoded %s\n  matter.js %s", got, f.BytesHex)
		}
	case "AuxiliaryAcl":
		var fx []struct {
			Privilege uint8    `json:"privilege"`
			AuthMode  uint8    `json:"authMode"`
			Subjects  []uint64 `json:"subjects"`
			Targets   []struct {
				Endpoint *uint16 `json:"endpoint"`
			} `json:"targets"`
			AuxiliaryType *uint8 `json:"auxiliaryType"`
			FabricIndex   uint8  `json:"fabricIndex"`
		}
		if err := json.Unmarshal(f.Fixture, &fx); err != nil {
			t.Fatal(err)
		}
		var v []mattercore.AccessControlAuxiliaryEntryStruct
		for _, e := range fx {
			entry := mattercore.AccessControlAuxiliaryEntryStruct{Entry: mattercore.AccessControlEntryStruct{FabricIndex: e.FabricIndex}}
			if e.AuxiliaryType == nil {
				entry.Redacted = true
			} else {
				entry.AuxiliaryType = *e.AuxiliaryType
				entry.Entry.Privilege, entry.Entry.AuthMode, entry.Entry.Subjects = e.Privilege, e.AuthMode, e.Subjects
				for _, tg := range e.Targets {
					entry.Entry.Targets = append(entry.Entry.Targets, mattercore.ACLTargetStruct{Endpoint: tg.Endpoint})
				}
			}
			v = append(v, entry)
		}
		if got := encodeValue(t, v); got != f.BytesHex {
			t.Fatalf("encoded %s\n  matter.js %s", got, f.BytesHex)
		}
	default:
		t.Fatalf("unknown attribute %s", f.Element)
	}
}

func checkGroupcastEventFixture(t *testing.T, f groupcastWireFixture) {
	t.Helper()
	switch f.Element {
	case "GroupcastTesting":
		var fx struct {
			SourceIPAddress      string  `json:"sourceIpAddress"`
			DestinationIPAddress string  `json:"destinationIpAddress"`
			GroupID              *uint16 `json:"groupId"`
			EndpointID           *uint16 `json:"endpointId"`
			ClusterID            *uint32 `json:"clusterId"`
			ElementID            *uint32 `json:"elementId"`
			AccessAllowed        *bool   `json:"accessAllowed"`
			GroupcastTestResult  uint8   `json:"groupcastTestResult"`
			FabricIndex          uint8   `json:"fabricIndex"`
		}
		if err := json.Unmarshal(f.Fixture, &fx); err != nil {
			t.Fatal(err)
		}
		ev := mattercore.GroupcastTestingEvent{
			SourceIPAddress: hexBytes(t, fx.SourceIPAddress), DestinationIPAddress: hexBytes(t, fx.DestinationIPAddress),
			GroupID: fx.GroupID, EndpointID: fx.EndpointID, ClusterID: fx.ClusterID, ElementID: fx.ElementID,
			AccessAllowed: fx.AccessAllowed, GroupcastTestResult: fx.GroupcastTestResult, FabricIndex: fx.FabricIndex,
		}
		if got := encodeValue(t, ev); got != f.BytesHex {
			t.Fatalf("encoded %s\n  matter.js %s", got, f.BytesHex)
		}
	case "AuxiliaryAccessUpdated":
		var fx struct {
			AdminNodeID *string `json:"adminNodeId"`
			FabricIndex uint8   `json:"fabricIndex"`
		}
		if err := json.Unmarshal(f.Fixture, &fx); err != nil {
			t.Fatal(err)
		}
		ev := mattercore.AuxiliaryAccessUpdatedEvent{FabricIndex: fx.FabricIndex}
		if fx.AdminNodeID != nil {
			n, err := strconv.ParseUint(*fx.AdminNodeID, 10, 64)
			if err != nil {
				t.Fatal(err)
			}
			ev.AdminNodeID = &n
		}
		if got := encodeValue(t, ev); got != f.BytesHex {
			t.Fatalf("encoded %s\n  matter.js %s", got, f.BytesHex)
		}
	default:
		t.Fatalf("unknown event %s", f.Element)
	}
}
